const IMGS: Record<string, { sha: string; b64: string }> = {
  "capacitacion": { sha: "5679054f176a1367011ffafd3881a67bf0b162d23b03481be18a57ae7f533ee7", b64: "" },
  "datos": { sha: "789671471907209815375c1a904d1dc538ed09ab374ba109102cc0873b0cd3ee", b64: "" },
  "automatizacion": { sha: "1781e1d5581403ba8c81a8eace0d533994b39af45a9543d3ee061629df292e23", b64: "" },
};
const BUF: Record<string, Uint8Array> = {};
for (const [k, v] of Object.entries(IMGS)) {
  const bytes = Uint8Array.from(atob(v.b64), (c) => c.charCodeAt(0));
  const hash = new Bun.CryptoHasher("sha256").update(bytes).digest("hex");
  console.log("img", k, bytes.length, hash === v.sha ? "OK" : "SHA_MISMATCH " + hash);
  BUF[k] = bytes;
}
Bun.serve({
  port: Number(Bun.env.PORT || 3000),
  fetch(req) {
    const p = new URL(req.url).pathname.replace(/^\//, "").replace(/\.webp$/, "");
    if (p === "health") return new Response("ok");
    const b = BUF[p];
    if (!b) return new Response("no encontrado", { status: 404 });
    return new Response(b, { headers: { "Content-Type": "image/webp", "Cache-Control": "public, max-age=604800", "Access-Control-Allow-Origin": "*" } });
  },
});
console.log("oatech-media listo");

